entries[12890] = { ["name"] = "Tiefer Schlummer", ["text"] = "30 Meter Reichweite\nWirken in 1 sek.\nReagenzien:\nSeelensplitter\nLässt einen Feind 15 Sek. lang in einen tiefen Schlaf versinken. Er kann dann nicht mehr agieren, ist aber gleichzeitig unverletzlich." }
entries[12891] = { ["name"] = "Säureatem", ["text"] = "Nahkampfreichweite\nSofort\nFügt jedem Feind in einem Kegel vor dem Zaubernden 10 Naturschaden und zusätzlich alle 5 Sek. 2 Schaden zu. Hält 45 Sek. lang an." }
entries[12895] = { ["name"] = "Pläne: Veredelter Mithrilzylinder", ["text"] = "Wirken in 25 sek.\nReagenzien:\nLeeres Pergament , Ingenieurstinte\nBenötigt Schmiedekunst\n(200)\nBenutzen: Lehrt Euch die Herstellung eines veredelten Mithrilzylinders. Dieser Gegenstand wird von Gnomeningenieuren verwendet." }
entries[12896] = { ["name"] = "Hölleneber" }
entries[12897] = { ["name"] = "Gnomenschutzbrille", ["text"] = "Wirken in 45 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nFeuerschutzbrille , Mithrilrohr , Goldkraftkern (2), Fläschchen Mojo (2), Schweres Leder (2)\nGnomenschutzbrille\nWird beim Aufheben gebunden\nKopf Stoff\n45 Rüstung\n+9 Ausdauer\n+9 Willenskraft\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst\n(210)\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 11." }
entries[12898] = { ["name"] = "Rauch-Aura - Bild" }
entries[12899] = { ["name"] = "Gnomenschrumpfstrahl", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilrohr , Instabiler Auslöser , Mithrilbarren (4), Fläschchen Mojo (4), Jade (2)\nWird beim Anlegen gebunden\nSchmuck\nBenötigt Ingenieurskunst\n(205)\nBenutzen: Lässt das Ziel schrumpfen und verringert seine Angriffskraft um 250. Zumindest ist das meistens der Fall... (5 Min Abklingzeit)" }
entries[12900] = { ["name"] = "Mobiler Alarm", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilrohr , Instabiler Auslöser , Mithrilbarren (4)" }
entries[12902] = { ["name"] = "Gnomen-Net-o-Matik-Projektor", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilrohr , Schattenseide (2), Dicke Spinnenseide (4), Robustes Sprengpulver (2), Mithrilbarren (4)\nWird beim Anlegen gebunden\nSchmuck\nBenötigt Ingenieurskunst\n(210)\nBenutzen: Hält das Ziel 20 Sek. lang in einem Netz fest. Das Netz ist allerdings mit einer Menge Haken bestückt und verfängt sich manchmal auch in der Kleidung des Benutzers, wenn es abgefeuert wird... (10 Min Abklingzeit)" }
entries[12903] = { ["name"] = "Gnomenunglücksverhinderungsgürtel", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSchwärzlicher Gürtel , Mithrilbarren (4), Echtsilberbarren (2), Instabiler Auslöser , Aquamarin (2)\nGnomenunglücksverhinderungsgürtel\nWird beim Anlegen gebunden\nTaille Leder\n66 Rüstung\n+6 Ausdauer\nHaltbarkeit 30 / 30\nBenötigt Ingenieurskunst\n(215)\nBenutzen: Ein Kraftfeldschild schützt Euch 10 Min. lang vor bis zu 500 Schaden.\nWARNUNG: Kraftfeld kann überladen werden, wenn es getroffen wird. Der Träger wird dann für gewisse Zeit aus dieser Dimension entfernt. (Procchance: 5%) (1 Stunde Abklingzeit)" }
entries[12904] = { ["name"] = "Gnomenamateurradio", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilgehäuse , Mithrilbarren (2), Gyrochronatom , Instabiler Auslöser" }
entries[12905] = { ["name"] = "Gnomenraketenstiefel", ["text"] = "Wirken in 12.5 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSchwarze Magiestoffstiefel , Mithrilrohr (2), Schweres Leder (4), Robustes Sprengpulver (8), Gyrochronatom (4)\nGnomenraketenstiefel\nWird beim Anlegen gebunden\nFüße Stoff\n41 Rüstung\nHaltbarkeit 35 / 35\nBenötigt Ingenieurskunst\n(225)\nBenutzen: Diese Stiefel erhöhen Euer Lauftempo 20 Sek. lang erheblich. WARNUNG: Ihre Stromversorgung und Gyros funktionieren nicht immer so, wie sie eigentlich sollten. (15 Min Abklingzeit)" }
entries[12906] = { ["name"] = "Gnomenkampfhuhn", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilgehäuse , Echtsilberbarren (6), Mithrilbarren (6), Veredelter Mithrilzylinder (2), Goldkraftkern , Jade (2)\nWird beim Aufheben gebunden\nSchmuck\nBenötigt Ingenieurskunst\n(230)\nBenutzen: Erschafft ein Kampfhuhn, das für 1.50 Min. oder bis es zerstört wird, für euch kämpfen wird. (20 Min Abklingzeit)" }
entries[12907] = { ["name"] = "Gnomengedankenkontrollkappe", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilbarren (10), Echtsilberbarren (4), Goldkraftkern , Sternrubin (2), Magiestoff (4)\nGnomengedankenkontrollkappe\nWird beim Anlegen gebunden\nKopf Stoff\n50 Rüstung\n+14 Willenskraft\nHaltbarkeit 45 / 45\nBenötigt Ingenieurskunst\n(215)" }
entries[12908] = { ["name"] = "Goblindrachenwerfer", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilrohr (2), Goblinraketentreibstoff (4), Mithrilbarren (6), Echtsilberbarren (6), Instabiler Auslöser\nWird beim Aufheben gebunden\nSchmuck\nBenutzen: Fügt jedem Feind in einem Kegel vor dem Ingenieur, der die Waffe benutzt, 10 Sek. lang 61 bis 69 Feuerschaden zu. Es sei denn, sie explodiert... (5 Min Abklingzeit)" }
