entries[13219] = { ["name"] = "Wundgift", ["text"] = "Wirken in 3 sek.\nBenötigt Nahkampfwaffe\nÜberzieht eine Waffe mit Gift, das eine Stunde lang wirkt.\nBei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften, wodurch dieser 17 Naturschaden erleidet und alle auf ihn gewirkten Heileffekte 15 Sek. lang um 10% verringert werden. Kann bis zu 5-mal auf ein einzelnes Ziel angewendet werden.\n(Procchance: 30%)" }
