entries[13240] = { ["name"] = "Der Mörser: Wieder aufgeladen", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGoblinmörser , Mithrilbarren , Robustes Sprengpulver (3)\nLädt einen leeren Goblinmörser wieder auf.\nGoblinmörser\nWird beim Anlegen gebunden\nSchmuck\nBenötigt Ingenieurskunst\n(205)\nBenutzen: Fügt 383 bis 517 Feuerschaden zu und betäubt 3 Sek. lang die Ziele in einem Umkreis von 5 Metern. (10 Min Abklingzeit)\n6 Aufladungen" }
