entries[13579] = { ["name"] = "Solarplexus", ["text"] = "Nahkampfreichweite\nSofort\nFügt einem Feind 20 Schaden zu und betäubt ihn bis zu 4 Sek. lang. Ihr stoppt alle Angriffe automatisch. Das Ziel muss Euch zugewandt sein. Jeder Schaden, der dem betäubten Ziel zugefügt wird, lässt es wieder aufwachen." }
