entries[14305] = { ["name"] = "Feuerbrandfalle", ["text"] = "245 Mana\nSofort 30 sek. Abklingzeit\nEine Feuerfalle platzieren, die dem ersten sich nähernden Feind 15 Sek. lang insgesamt (Fernkampfangriffskraft * 0.1 + 138 * 5) Feuerschaden zufügt. Die Falle bleibt 1 Min. lang bestehen. Es kann immer nur jeweils eine Falle aktiv sein." }
entries[14308] = { ["name"] = "Eiskältefalle" }
entries[14309] = { ["name"] = "Eiskältefalle" }
entries[14310] = { ["name"] = "Eiskältefalle", ["text"] = "75 Mana\nSofort 30 sek. Abklingzeit\nEine Eiskältefalle platzieren, die den ersten sich nähernden Feind einfriert und 15 Sek. lang jegliche Aktion des Feindes verhindert. Jeglicher erlittener Schaden wird das Eis wieder brechen. Die Falle bleibt 1 Min. lang bestehen. Es kann immer nur jeweils eine Falle aktiv sein." }
entries[14311] = { ["name"] = "Eiskältefalle", ["text"] = "100 Mana\nSofort 30 sek. Abklingzeit\nEine Eiskältefalle platzieren, die den ersten sich nähernden Feind einfriert und 20 Sek. lang jegliche Aktion des Feindes verhindert. Jeglicher erlittener Schaden wird das Eis wieder brechen. Die Falle bleibt 1 Min. lang bestehen. Es kann immer nur jeweils eine Falle aktiv sein." }
entries[14314] = { ["name"] = "Sprengfalle" }
entries[14315] = { ["name"] = "Sprengfalle" }
entries[14316] = { ["name"] = "Sprengfalle", ["text"] = "395 Mana\nSofort 30 sek. Abklingzeit\nEine Feuerfalle platzieren, die explodiert, wenn sich ein Feind nähert. Die Falle verursacht (Fernkampfangriffskraft * 0.1 + 139) bis (Fernkampfangriffskraft * 0.1 + 187) Feuerschaden und verbrennt alle Feinde in einem Umkreis von 10 Metern, indem sie ihnen 20 Sek. lang insgesamt 240 zusätzlichen Feuerschaden zufügt. Die Falle bleibt 1 Min. lang bestehen. Es kann immer nur jeweils eine Falle aktiv sein." }
entries[14317] = { ["name"] = "Sprengfalle", ["text"] = "520 Mana\nSofort 30 sek. Abklingzeit\nEine Feuerfalle platzieren, die explodiert, wenn sich ein Feind nähert. Die Falle verursacht (Fernkampfangriffskraft * 0.1 + 201) bis (Fernkampfangriffskraft * 0.1 + 257) Feuerschaden und verbrennt alle Feinde in einem Umkreis von 10 Metern, indem sie ihnen 20 Sek. lang insgesamt 330 zusätzlichen Feuerschaden zufügt. Die Falle bleibt 1 Min. lang bestehen. Es kann immer nur jeweils eine Falle aktiv sein." }
entries[14318] = { ["name"] = "Aspekt des Falken", ["text"] = "35 Mana\nSofort\nDer Jäger nimmt die Aspekte eines Falken an: Die Distanzangriffskraft wird um 35 erhöht. Es kann immer nur jeweils ein Aspekt aktiv sein." }
entries[14319] = { ["name"] = "Aspekt des Falken", ["text"] = "50 Mana\nSofort\nDer Jäger nimmt die Aspekte eines Falken an: Die Distanzangriffskraft wird um 50 erhöht. Es kann immer nur jeweils ein Aspekt aktiv sein." }
entries[14320] = { ["name"] = "Aspekt des Falken", ["text"] = "70 Mana\nSofort\nDer Jäger nimmt die Aspekte eines Falken an: Die Distanzangriffskraft wird um 70 erhöht. Es kann immer nur jeweils ein Aspekt aktiv sein." }
entries[14321] = { ["name"] = "Aspekt des Falken", ["text"] = "90 Mana\nSofort\nDer Jäger nimmt die Aspekte eines Falken an: Die Distanzangriffskraft wird um 90 erhöht. Es kann immer nur jeweils ein Aspekt aktiv sein." }
entries[14322] = { ["name"] = "Aspekt des Falken", ["text"] = "110 Mana\nSofort\nDer Jäger nimmt die Aspekte eines Falken an: Die Distanzangriffskraft wird um 110 erhöht. Es kann immer nur jeweils ein Aspekt aktiv sein." }
entries[14323] = { ["name"] = "Mal des Jägers", ["text"] = "30 Mana 100 Meter Reichweite\nSofort\nLegt das Mal des Jägers auf das Ziel und erhöht dabei die Distanzangriffskraft aller Angreifer gegen dieses Ziel um 45 sowie jedesmal, wenn es durch einen Distanzangriff getroffen wird, um zusätzliche 5 bis zu einem Höchstbetrag von 180. Zusätzlich ist mit dieser Fähigkeit das Ziel immer sichtbar, auch wenn es in den Verstohlenheitsmodus geht oder unsichtbar wird. Das Ziel wird außerdem auf der Minikarte angezeigt. Hält 2 Min. lang an." }
entries[14324] = { ["name"] = "Mal des Jägers", ["text"] = "45 Mana 100 Meter Reichweite\nSofort\nLegt das Mal des Jägers auf das Ziel und erhöht dabei die Distanzangriffskraft aller Angreifer gegen dieses Ziel um 75 sowie jedesmal, wenn es durch einen Distanzangriff getroffen wird, um zusätzliche 8 bis zu einem Höchstbetrag von 300. Zusätzlich ist mit dieser Fähigkeit das Ziel immer sichtbar, auch wenn es in den Verstohlenheitsmodus geht oder unsichtbar wird. Das Ziel wird außerdem auf der Minikarte angezeigt. Hält 2 Min. lang an." }
entries[14325] = { ["name"] = "Mal des Jägers", ["text"] = "60 Mana 100 Meter Reichweite\nSofort\nLegt das Mal des Jägers auf das Ziel und erhöht dabei die Distanzangriffskraft aller Angreifer gegen dieses Ziel um 110 sowie jedesmal, wenn es durch einen Distanzangriff getroffen wird, um zusätzliche 11 bis zu einem Höchstbetrag von 440. Zusätzlich ist mit dieser Fähigkeit das Ziel immer sichtbar, auch wenn es in den Verstohlenheitsmodus geht oder unsichtbar wird. Das Ziel wird außerdem auf der Minikarte angezeigt. Hält 2 Min. lang an." }
entries[14326] = { ["name"] = "Wildtier ängstigen", ["text"] = "50 Mana 30 Meter Reichweite\nWirken in 1.5 sek. 30 sek. Abklingzeit\nJagt einem Wildtier Angst ein, woraufhin es bis zu 15 Sek. lang voller Furcht wegläuft. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils ein Wildtier mit dem Furchteffekt versehen werden." }
entries[14327] = { ["name"] = "Wildtier ängstigen", ["text"] = "75 Mana 30 Meter Reichweite\nWirken in 1.5 sek. 30 sek. Abklingzeit\nJagt einem Wildtier Angst ein, woraufhin es bis zu 20 Sek. lang voller Furcht wegläuft. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils ein Wildtier mit dem Furchteffekt versehen werden." }
